sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 1. Parse the incoming JSON payload
    var requestBody = request.body.data;

    // 2. Map payload to your Release Gate table
    var grRelease = new GlideRecord('x_1858206_sentin_0_release_gate');
    grRelease.initialize();

    grRelease.release_name = requestBody.release_name;
    grRelease.tech_debt_score = requestBody.tech_debt_score; 

    // 3. Insert the record into the database
    var sysId = grRelease.insert();

    // 4. Return a success response
    response.setStatus(201); // HTTP 201: Created
    response.setBody({
        "status": "Success",
        "message": "SentinelOps ingested release data.",
        "record_id": sysId
    });

})(request, response);
